scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_292'] || []

control 'CKV_AWS_292' do
  title 'Ensure DocumentDB Global Cluster is encrypted at rest (default is unencrypted)'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_docdb_global_cluster resources that actually exist, enumerated
    through the declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    A global cluster replicates the data into additional regions. If the
    global cluster is unencrypted then every regional copy is unencrypted,
    which multiplies one configuration mistake across every region the data
    has been replicated into.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_docdb_global_cluster: storage_encrypted is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_docdb_global_cluster:

      resource "aws_docdb_global_cluster" "docs" {
        global_cluster_identifier = "docs-global"
        engine                    = "docdb"
        engine_version            = "5.0.0"
        storage_encrypted         = true
      }

    Out of band — aws_docdb_global_cluster:

      There is no in-place fix. StorageEncrypted on a global cluster is set at
      creation. Create a new encrypted global cluster and attach regional
      clusters restored from encrypted snapshots, then delete the old one.
  FIX

  tag checkov_id:            'CKV_AWS_292'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_docdb_global_cluster]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/docdb_global_cluster#storage-encrypted'
  tag nist:                  ['SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_docdb_global_cluster', regions: scan_regions)

  # A field the API did not return is nil, and nil is not a failing value:
  # the asset does not express this setting, so it is out of scope for this
  # check rather than in breach of it.
  in_scope = assets.assets(exempt: exempt)
                   .reject { |a| a[:storage_encrypted].nil? }

  applicable = !in_scope.empty?
  impact 0.7
  impact 0.0 unless applicable
  only_if('no aws_docdb_global_cluster in scope expressing this setting') { applicable }

  in_scope.each do |asset|
    describe "aws_docdb_global_cluster #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:storage_encrypted] }
      it { should eq true }
    end
  end
end
